sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var mainobj = new getProblemDetails();
	var inc = new GlideRecord('incident');
	inc.initialize();
	inc.problem_id = current.sys_id;
	inc.caller_id = gs.getUserID();
	inc.short_description = 'This incident was created due to priority of Problem ' + current.getDisplayValue('number') + 'changed to critical';
	inc.description = 'Tasks associated with probleml are : '+mainobj.getProblemTask(current.sys_id) + '\n Groups of Assignee : ' + mainobj.getUserGroup(current.assigned_to);
	inc.insert();
})(current, previous);
